/**
 * Check if a given object implements the EarningsItem interface.
 */
export function instanceOfEarningsItem(value) {
    if (!("date" in value) || value["date"] === undefined)
        return false;
    return true;
}
export function EarningsItemFromJSON(json) {
    return EarningsItemFromJSONTyped(json, false);
}
export function EarningsItemFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        date: json["date"],
        time: json["time"] == null ? undefined : json["time"],
        epsEstimate: json["eps_estimate"] == null ? undefined : json["eps_estimate"],
        epsActual: json["eps_actual"] == null ? undefined : json["eps_actual"],
        difference: json["difference"] == null ? undefined : json["difference"],
        surprisePrc: json["surprise_prc"] == null ? undefined : json["surprise_prc"],
    };
}
export function EarningsItemToJSON(json) {
    return EarningsItemToJSONTyped(json, false);
}
export function EarningsItemToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        date: value["date"],
        time: value["time"],
        eps_estimate: value["epsEstimate"],
        eps_actual: value["epsActual"],
        difference: value["difference"],
        surprise_prc: value["surprisePrc"],
    };
}
